using UnityEngine;

namespace Framework.Grid
{
    /// <summary>
    /// UnityのGridを利用して、グリッド座標と
    /// ワールド座標の相互変換を行うコンポーネント。
    /// </summary>
    [DisallowMultipleComponent]
    [RequireComponent(typeof(UnityEngine.Grid))]
    public class GridCoordinateConverter : MonoBehaviour
    {
        #region Fields

        /// <summary>
        /// 座標変換に使用するGridコンポーネント。
        /// </summary>
        private UnityEngine.Grid grid;

        #endregion

        #region Properties

        /// <summary>
        /// 座標変換に使用するGridコンポーネントを取得する。
        /// 未取得の場合は自動的に取得する。
        /// </summary>
        public UnityEngine.Grid GridComponent
        {
            get
            {
                if (grid == null)
                {
                    grid = GetComponent<UnityEngine.Grid>();
                }

                return grid;
            }
        }

        /// <summary>
        /// 1マス分のセルサイズを取得する。
        /// </summary>
        public Vector3 CellSize => GridComponent.cellSize;

        /// <summary>
        /// セル間の間隔を取得する。
        /// </summary>
        public Vector3 CellGap => GridComponent.cellGap;

        #endregion

        #region Unity Methods

        /// <summary>
        /// コンポーネントの初期化処理。
        /// </summary>
        private void Awake()
        {
            // 同一GameObjectのGridを取得する。
            grid = GetComponent<UnityEngine.Grid>();
        }

        #endregion

        #region Cell To World

        /// <summary>
        /// グリッド座標をワールド座標に変換する。
        /// マスの原点に相当する座標を返す。
        /// </summary>
        /// <param name="cellPosition">
        /// 変換対象のグリッド座標
        /// </param>
        /// <returns>変換後のワールド座標</returns>
        public Vector3 CellToWorld(Vector3Int cellPosition)
        {
            return GridComponent.CellToWorld(cellPosition);
        }

        /// <summary>
        /// 二次元グリッド座標をワールド座標に変換する。
        /// </summary>
        /// <param name="cellPosition">
        /// 変換対象の二次元グリッド座標
        /// </param>
        /// <param name="z">グリッド上のZ座標</param>
        /// <returns>変換後のワールド座標</returns>
        public Vector3 CellToWorld(
            Vector2Int cellPosition,
            int z = 0)
        {
            return CellToWorld(
                ToVector3Int(cellPosition, z));
        }

        #endregion

        #region World To Cell

        /// <summary>
        /// ワールド座標をグリッド座標に変換する。
        /// </summary>
        /// <param name="worldPosition">
        /// 変換対象のワールド座標
        /// </param>
        /// <returns>変換後のグリッド座標</returns>
        public Vector3Int WorldToCell(Vector3 worldPosition)
        {
            return GridComponent.WorldToCell(worldPosition);
        }

        /// <summary>
        /// ワールド座標を二次元グリッド座標に変換する。
        /// Z座標は返却値に含めない。
        /// </summary>
        /// <param name="worldPosition">
        /// 変換対象のワールド座標
        /// </param>
        /// <returns>変換後の二次元グリッド座標</returns>
        public Vector2Int WorldToCell2D(Vector3 worldPosition)
        {
            // Unity標準の座標変換を行う。
            Vector3Int cellPosition = WorldToCell(worldPosition);

            return ToVector2Int(cellPosition);
        }

        #endregion

        #region Cell Center

        /// <summary>
        /// 指定されたマスの中心ワールド座標を取得する。
        /// </summary>
        /// <param name="cellPosition">
        /// 取得対象のグリッド座標
        /// </param>
        /// <returns>マスの中心ワールド座標</returns>
        public Vector3 GetCellCenterWorld(
            Vector3Int cellPosition)
        {
            return GridComponent.GetCellCenterWorld(
                cellPosition);
        }

        /// <summary>
        /// 指定された二次元マスの中心ワールド座標を取得する。
        /// </summary>
        /// <param name="cellPosition">
        /// 取得対象の二次元グリッド座標
        /// </param>
        /// <param name="z">グリッド上のZ座標</param>
        /// <returns>マスの中心ワールド座標</returns>
        public Vector3 GetCellCenterWorld(
            Vector2Int cellPosition,
            int z = 0)
        {
            return GetCellCenterWorld(
                ToVector3Int(cellPosition, z));
        }

        #endregion

        #region Snap

        /// <summary>
        /// 指定されたワールド座標を、
        /// 所属するマスの中心座標に補正する。
        /// </summary>
        /// <param name="worldPosition">
        /// 補正対象のワールド座標
        /// </param>
        /// <returns>補正後のワールド座標</returns>
        public Vector3 SnapToCellCenter(
            Vector3 worldPosition)
        {
            // 現在位置が所属するマスを取得する。
            Vector3Int cellPosition =
                WorldToCell(worldPosition);

            // 所属するマスの中心座標を返す。
            return GetCellCenterWorld(cellPosition);
        }

        /// <summary>
        /// 指定されたTransformを、
        /// 所属するマスの中心座標に移動する。
        /// </summary>
        /// <param name="target">移動対象のTransform</param>
        public void SnapTransformToCellCenter(
            Transform target)
        {
            // 移動対象が存在しない場合は処理しない。
            if (target == null)
            {
                return;
            }

            target.position =
                SnapToCellCenter(target.position);
        }

        #endregion

        #region Utility Methods

        /// <summary>
        /// 二次元整数座標を三次元整数座標に変換する。
        /// </summary>
        /// <param name="position">変換対象の二次元座標</param>
        /// <param name="z">変換後のZ座標</param>
        /// <returns>変換後の三次元整数座標</returns>
        public static Vector3Int ToVector3Int(
            Vector2Int position,
            int z = 0)
        {
            return new Vector3Int(
                position.x,
                position.y,
                z);
        }

        /// <summary>
        /// 三次元整数座標を二次元整数座標に変換する。
        /// </summary>
        /// <param name="position">変換対象の三次元座標</param>
        /// <returns>変換後の二次元整数座標</returns>
        public static Vector2Int ToVector2Int(
            Vector3Int position)
        {
            return new Vector2Int(
                position.x,
                position.y);
        }

        #endregion
    }
}
